update public.products set description='Fresh goat offal suited to frying, sauces, stews and other thoroughly cooked dishes.', handling_protocols=array['Keep refrigerated and separate from ready-to-eat foods.','Clean hands, utensils and preparation surfaces after handling.','Cook thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','Freeze at about -18°C or below for longer storage and use within about 3–4 months for best quality.']::text[] where name='Goat Liver' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
